-- Finite 40-field source schema for initial-view prefix/cache isolation.
-- Consumer: tests/support/source_initial_view_app.inc via --source-opens-only.
COPY (SELECT CAST('2026-10-25 12:00:00' AS TIMESTAMP) + (row_number() OVER ()-1)*INTERVAL '1 day' AS Moment,
    Amount AS Field01,
    2::BIGINT AS Field02,
    3::BIGINT AS Field03,
    4::BIGINT AS Field04,
    5::BIGINT AS Field05,
    6::BIGINT AS Field06,
    7::BIGINT AS Field07,
    8::BIGINT AS Field08,
    9::BIGINT AS Field09,
    10::BIGINT AS Field10,
    11::BIGINT AS Field11,
    12::BIGINT AS Field12,
    13::BIGINT AS Field13,
    14::BIGINT AS Field14,
    15::BIGINT AS Field15,
    16::BIGINT AS Field16,
    17::BIGINT AS Field17,
    18::BIGINT AS Field18,
    19::BIGINT AS Field19,
    20::BIGINT AS Field20,
    21::BIGINT AS Field21,
    22::BIGINT AS Field22,
    23::BIGINT AS Field23,
    24::BIGINT AS Field24,
    25::BIGINT AS Field25,
    26::BIGINT AS Field26,
    27::BIGINT AS Field27,
    28::BIGINT AS Field28,
    29::BIGINT AS Field29,
    30::BIGINT AS Field30,
